import { useEffect, useMemo, useRef, useState } from 'react';
import { AccessibilityInfo, KeyboardAvoidingView, Platform, ScrollView, StyleSheet, Text, TextInput, TouchableOpacity, View, useWindowDimensions } from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';

type Tab = 'today' | 'vehicles' | 'deals' | 'maintenance' | 'customers';
type Route = { type: 'tab' | 'vehicle' | 'purchase' | 'customer' | 'customerCreate' | 'dealCreate' | 'deal' | 'dealCancel' | 'maintenanceCreate' | 'maintenance' | 'jobBilling' | 'quoteCreate' | 'appointmentCreate' | 'paymentCreate' | 'delivery' | 'photo'; tab: Tab; id?: string; step?: number };
type Vehicle = { id: string; name: string; number: string; status: string; days: number; cost: number; margin: number; supplier: string; supplierType?: string; purchaseDate?: string; mileage?: string; price: number; costBreakdown?: Record<string, number>; photos: string[] };
type Customer = { id: string; name: string; phone: string; email?: string; kind?: string; address?: string; desiredVehicle?: string; budget?: string; purchaseTiming?: string; tradeIn?: string; staff?: string; next?: string; note?: string };
type Deal = { id: string; customerId: string; vehicleId: string; status: string; next: string; staff: string; certainty: string; source?: string; budget?: string; tradeIn?: string; loanWish?: string; note?: string; quoteItem?: string; quoteAmount?: string; paidAmount?: string; paymentMethod?: string; delivered?: boolean };
type Job = { id: string; customerId: string; vehicleId: string; request: string; symptom: string; staff: string; status: string; date: string; workItems?: string; parts?: string; workInstruction?: string; priority?: string; workSchedule?: string; deliveryPlan?: string; actualDates?: string; loaner?: string; laborCost?: string; partsCost?: string; inspectionFees?: string; adjustments?: string; estimateInvoice?: string; estimateApproval?: string; paymentMethod?: string; quoteItem?: string; quoteAmount?: string; billedAmount?: string; photos?: string[] };
type Appointment = { id: string; name: string; when: string; subject: string; customerId?: string; vehicleId?: string; dealId?: string };

const initialVehicles: Vehicle[] = [
  { id: 'v1', name: 'トヨタ プロボックス', number: 'GL-2401', status: '在庫中', days: 41, cost: 1230000, margin: 270000, supplier: '大阪オートオークション', price: 1500000, photos: ['仕入時', '入庫時'] },
  { id: 'v2', name: 'スズキ ハスラー', number: 'GL-2402', status: '整備中', days: 12, cost: 980000, margin: 220000, supplier: '山田 太郎', price: 1200000, photos: ['入庫時', '整備中'] },
];
const initialCustomers: Customer[] = [{ id: 'c1', name: '佐藤 花子', phone: '090-1234-5678' }, { id: 'c2', name: '株式会社みなと', phone: '06-1234-5678' }];
const initialDeals: Deal[] = [{ id: 'd1', customerId: 'c1', vehicleId: 'v1', status: '見積前', next: '昨日 18:00まで', staff: '田中', certainty: '60%' }, { id: 'd2', customerId: 'c2', vehicleId: 'v2', status: '見積提示済み', next: '明日 10:00', staff: '佐々木', certainty: '80%' }];
const initialJobs: Job[] = [{ id: 'm1', customerId: 'c1', vehicleId: 'v2', request: '12か月点検', symptom: 'ブレーキから音がする', staff: '田中', status: '入庫待ち', date: '今日 13:00' }];
const initialAppointments: Appointment[] = [{ id: 'a1', name: '車両相談', when: '10:30', subject: '佐藤 花子', customerId: 'c1' }, { id: 'a2', name: '12か月点検', when: '13:00', subject: 'GL-2402', vehicleId: 'v2' }];
const tabs: { id: Tab; label: string; glyph: string }[] = [
  { id: 'today', label: '今日', glyph: '◷' }, { id: 'vehicles', label: '車両', glyph: '▱' }, { id: 'deals', label: '商談', glyph: '◇' }, { id: 'maintenance', label: '整備', glyph: '⚒' }, { id: 'customers', label: '顧客', glyph: '♙' },
];
const photoKinds = ['仕入時', '入庫時', '整備前', '整備中', '整備後', '傷・不具合', '納車時'];
const tokyoDate = new Intl.DateTimeFormat('en', { timeZone: 'Asia/Tokyo', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date());
const todayString = `${tokyoDate.find((part) => part.type === 'year')?.value}-${tokyoDate.find((part) => part.type === 'month')?.value}-${tokyoDate.find((part) => part.type === 'day')?.value}`;

export default function GarageMobileV2Prototype() {
  const { width } = useWindowDimensions();
  const compact = width < 380;
  const [route, setRoute] = useState<Route>({ type: 'tab', tab: 'today' });
  const [stack, setStack] = useState<Route[]>([]);
  const [vehicles, setVehicles] = useState(initialVehicles);
  const [customers, setCustomers] = useState(initialCustomers);
  const [deals, setDeals] = useState(initialDeals);
  const [jobs, setJobs] = useState(initialJobs);
  const [appointments, setAppointments] = useState(initialAppointments);
  const [vehicleTab, setVehicleTab] = useState('基本');
  const [search, setSearch] = useState('');
  const [toast, setToast] = useState('');
  const [error, setError] = useState('');
  const [selectedPhotoKind, setSelectedPhotoKind] = useState('仕入時');
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});
  const [maintenanceTab, setMaintenanceTab] = useState('受付');
  const [draft, setDraft] = useState<Record<string, string>>({ purchaseDate: todayString, dealStatus: '新規', staff: '田中', intakeDate: todayString, appointmentDate: todayString });
  const toastTimer = useRef<ReturnType<typeof setTimeout> | null>(null);

  const push = (next: Route) => { setError(''); setStack((current) => [...current, route]); setRoute(next); };
  const back = () => { setError(''); setRoute(stack.at(-1) ?? { type: 'tab', tab: route.tab }); setStack((current) => current.slice(0, -1)); };
  const goTab = (tab: Tab) => { setError(''); setStack([]); setRoute({ type: 'tab', tab }); };
  const update = (key: string, value: string) => { setDraft((current) => ({ ...current, [key]: value })); setError(''); };
  const clearDraftFields = (...keys: string[]) => setDraft((current) => { const next = { ...current }; keys.forEach((key) => delete next[key]); return next; });
  const toggleExpanded = (key: string) => setExpanded((current) => ({ ...current, [key]: !current[key] }));
  const value = (key: string) => draft[key] ?? '';
  const notify = (message: string) => { if (toastTimer.current) clearTimeout(toastTimer.current); setToast(message); toastTimer.current = setTimeout(() => setToast(''), 2600); };
  useEffect(() => () => { if (toastTimer.current) clearTimeout(toastTimer.current); }, []);
  useEffect(() => { if (toast && Platform.OS !== 'web') AccessibilityInfo.announceForAccessibility(toast); }, [toast]);
  const customerById = (id: string) => customers.find((item) => item.id === id);
  const vehicleById = (id: string) => vehicles.find((item) => item.id === id);
  const customerOption = (item: Customer) => `${item.name} · ${item.phone}`;
  const vehicleOption = (item: Vehicle) => `${item.name} · ${item.number}`;
  const currentVehicle = vehicles.find((item) => item.id === route.id);
  const currentCustomer = customers.find((item) => item.id === route.id);
  const currentDeal = deals.find((item) => item.id === route.id);
  const currentJob = jobs.find((item) => item.id === route.id);
  const currentVehicleExtraCosts = currentVehicle?.costBreakdown ? Object.entries(currentVehicle.costBreakdown).reduce((sum, [key, amount]) => sum + (key === 'purchasePrice' ? 0 : amount), 0) : undefined;
  const overdueDeal = deals.find((item) => item.id === 'd1');
  const followUpDeal = deals.find((item) => item.id === 'd2');
  const intakeJob = jobs.find((item) => item.id === 'm1');
  const deliveryDeal = deals.find((item) => item.status === '入金済み');
  const filteredVehicles = useMemo(() => vehicles.filter((item) => `${item.name} ${item.number}`.toLowerCase().includes(search.toLowerCase())), [vehicles, search]);
  const filteredCustomers = useMemo(() => customers.filter((item) => `${item.name} ${item.phone}`.toLowerCase().includes(search.toLowerCase())), [customers, search]);

  const saveCustomer = () => {
    if (!value('customerName').trim() || !value('customerPhone').trim()) { setError('名前と電話番号を入力してください。'); return; }
    const item: Customer = { id: route.id ?? `c${Date.now()}`, name: value('customerName').trim(), phone: value('customerPhone').trim(), email: value('customerEmail').trim(), kind: value('customerType') || '個人', address: value('customerAddress').trim(), desiredVehicle: value('desiredVehicle').trim(), budget: value('customerBudget').trim(), purchaseTiming: value('purchaseTiming').trim(), tradeIn: value('tradeIn').trim(), staff: value('customerStaff').trim(), next: value('customerNext').trim(), note: value('customerNote').trim() };
    if (route.id) setCustomers((list) => list.map((customer) => customer.id === route.id ? item : customer));
    else setCustomers((list) => [item, ...list]);
    clearDraftFields('customerName', 'customerPhone', 'customerEmail', 'customerType', 'customerAddress', 'desiredVehicle', 'customerBudget', 'purchaseTiming', 'tradeIn', 'customerStaff', 'customerNext', 'customerNote');
    setExpanded((current) => ({ ...current, customerDetails: false }));
    if (route.id) { notify('顧客情報を更新しました'); back(); }
    else { notify('顧客を保存しました'); goTab('customers'); }
  };
  const saveAppointment = () => {
    if (!value('appointmentName').trim()) { setError('予約内容を入力してください。'); return; }
    setAppointments((items) => [{ id: `a${Date.now()}`, name: value('appointmentName').trim(), when: value('appointmentDate') || todayString, subject: value('appointmentSubject') || '未指定', customerId: value('appointmentCustomerId') || undefined, vehicleId: value('appointmentVehicleId') || undefined, dealId: value('appointmentDealId') || undefined }, ...items]);
    clearDraftFields('appointmentName', 'appointmentSubject', 'appointmentCustomerId', 'appointmentVehicleId', 'appointmentDealId');
    update('appointmentDate', todayString);
    notify('予約を保存しました');
    back();
  };
  const saveVehicle = () => {
    if (!value('vehicleName').trim() || !value('supplier').trim() || !value('purchasePrice').trim()) { setError('車名・仕入先・仕入価格を入力してください。'); return; }
    const price = Number(value('purchasePrice')) || 0;
    const extraCost = ['specialCost', 'accessoryCost', 'agentCost', 'legalCost', 'otherCost', 'repairCost'].reduce((sum, key) => sum + (Number(value(key)) || 0), 0);
    const totalCost = price + extraCost;
    const askingPrice = Number(value('askingPrice')) || totalCost;
    const item: Vehicle = { id: `v${Date.now()}`, name: value('vehicleName').trim(), number: value('managementNo').trim() || '仮登録', status: '在庫中', days: 0, cost: totalCost, margin: askingPrice - totalCost, supplier: value('supplier').trim(), supplierType: value('supplierType') || 'オークション', purchaseDate: value('purchaseDate') || todayString, mileage: value('mileage').trim(), price: askingPrice, costBreakdown: { purchasePrice: price, specialCost: Number(value('specialCost')) || 0, accessoryCost: Number(value('accessoryCost')) || 0, agentCost: Number(value('agentCost')) || 0, legalCost: Number(value('legalCost')) || 0, otherCost: Number(value('otherCost')) || 0, repairCost: Number(value('repairCost')) || 0 }, photos: [selectedPhotoKind] };
    setVehicles((list) => [item, ...list]); clearDraftFields('vehicleName', 'managementNo', 'mileage', 'odometer', 'supplier', 'supplierType', 'purchasePrice', 'askingPrice', 'specialCost', 'accessoryCost', 'agentCost', 'legalCost', 'otherCost', 'repairCost'); update('purchaseDate', todayString); setSelectedPhotoKind('仕入時'); setExpanded((current) => ({ ...current, vehicleCosts: false })); notify('車両を仮登録しました'); goTab('vehicles');
  };
  const saveDeal = () => {
    const customerId = value('dealCustomerId');
    const vehicleId = value('dealVehicleId');
    if (!customerId || !vehicleId) { setError('顧客と車両を選択してください。'); return; }
    const item: Deal = { id: `d${Date.now()}`, customerId, vehicleId, status: '新規', next: value('dealNext') || '未設定', staff: value('dealStaff') || '田中', certainty: value('dealCertainty') || '30%', source: value('dealSource').trim(), budget: value('dealBudget').trim(), tradeIn: value('dealTradeIn').trim(), loanWish: value('loanWish'), note: value('dealNote').trim() };
    setDeals((list) => [item, ...list]); clearDraftFields('dealCustomerId', 'dealVehicleId', 'dealNext', 'dealStaff', 'dealCertainty', 'dealSource', 'dealBudget', 'dealTradeIn', 'loanWish', 'dealNote'); notify('商談を保存しました'); goTab('deals');
  };
  const saveJob = () => {
    const customerId = value('jobCustomerId');
    const vehicleId = value('jobVehicleId');
    if (!customerId || !vehicleId || !value('jobRequest').trim() || !value('jobSymptom').trim()) { setError('顧客・車両・依頼内容・症状を入力してください。'); return; }
    const item: Job = { id: `m${Date.now()}`, customerId, vehicleId, request: value('jobRequest').trim(), symptom: value('jobSymptom').trim(), staff: value('jobStaff') || '田中', status: '受付', date: value('intakeDate') || todayString, photos: [] };
    setJobs((list) => [item, ...list]); clearDraftFields('jobCustomerId', 'jobVehicleId', 'jobRequest', 'jobSymptom', 'jobStaff', 'intakeDate', 'workItems', 'parts', 'workInstruction', 'priority', 'workSchedule', 'deliveryPlan', 'actualDates', 'loaner', 'laborCost', 'partsCost', 'inspectionFees', 'adjustments', 'estimateInvoice', 'estimateApproval', 'jobPaymentMethod', 'jobBilledAmount'); update('intakeDate', todayString); notify('整備を受付しました'); goTab('maintenance');
  };
  const openDeal = (deal: Deal) => push({ type: 'deal', tab: 'deals', id: deal.id });
  const openCustomerDeal = (customerId: string) => { clearDraftFields('dealVehicleId'); update('dealCustomerId', customerId); push({ type: 'dealCreate', tab: 'customers' }); };
  const openVehicleDeal = (vehicleId: string) => { clearDraftFields('dealCustomerId'); update('dealVehicleId', vehicleId); push({ type: 'dealCreate', tab: 'vehicles' }); };
  const openJobCreate = (customerId?: string, vehicleId?: string) => { clearDraftFields('jobCustomerId', 'jobVehicleId'); if (customerId) update('jobCustomerId', customerId); if (vehicleId) update('jobVehicleId', vehicleId); setMaintenanceTab('受付'); push({ type: 'maintenanceCreate', tab: route.tab }); };
  const openJob = (job: Job) => { setMaintenanceTab('受付'); update('workItems', job.workItems || ''); update('parts', job.parts || ''); update('workInstruction', job.workInstruction || ''); update('priority', job.priority || ''); update('workSchedule', job.workSchedule || ''); update('deliveryPlan', job.deliveryPlan || ''); update('actualDates', job.actualDates || ''); update('loaner', job.loaner || ''); update('laborCost', job.laborCost || ''); update('partsCost', job.partsCost || ''); update('inspectionFees', job.inspectionFees || ''); update('adjustments', job.adjustments || ''); update('estimateInvoice', job.estimateInvoice || ''); update('estimateApproval', job.estimateApproval || ''); update('jobPaymentMethod', job.paymentMethod || ''); push({ type: 'maintenance', tab: 'maintenance', id: job.id }); };
  const dealPrimary = (deal: Deal) => {
    if (deal.status === '新規' || deal.status === '見積前') push({ type: 'quoteCreate', tab: 'deals', id: deal.id });
    else if (deal.status === '見積提示済み') { setDeals((items) => items.map((item) => item.id === deal.id ? { ...item, status: '成約' } : item)); notify('成約に更新しました'); }
    else if (deal.status === '成約') push({ type: 'paymentCreate', tab: 'deals', id: deal.id });
    else if (deal.status === '入金済み') push({ type: 'delivery', tab: 'deals', id: deal.id });
    else notify('次の作業はありません');
  };

  const title = route.type === 'tab' ? tabs.find((item) => item.id === route.tab)?.label : ({ vehicle: '車両詳細', purchase: route.step === 1 ? '仕入登録 1/3' : route.step === 2 ? '仕入登録 2/3' : '仕入登録 3/3', customer: '顧客詳細', customerCreate: route.id ? '顧客編集' : '顧客登録', dealCreate: '商談作成', deal: '商談詳細', dealCancel: '売約取消の確認', maintenanceCreate: '整備受付', maintenance: '整備詳細', jobBilling: '整備請求', quoteCreate: '見積作成', appointmentCreate: '予約登録', paymentCreate: '入金登録', delivery: '納車確認', photo: '写真を追加' } as Record<string, string>)[route.type] ?? '';

  return <SafeAreaView style={s.safe} edges={['top', 'left', 'right']}>
    <View style={s.header}>
      {route.type !== 'tab' ? <TouchableOpacity onPress={back} accessibilityRole="button" style={s.back}><Text style={s.backText}>‹ 戻る</Text></TouchableOpacity> : <View style={s.back} />}
      <View style={s.headerCenter}><Text style={s.headerTitle} numberOfLines={1}>{title}</Text><Text style={s.demoTag}>試作データ・端末内のみ</Text></View>
      <TouchableOpacity accessibilityRole="button" onPress={() => { setVehicles(initialVehicles); setCustomers(initialCustomers); setDeals(initialDeals); setJobs(initialJobs); setAppointments(initialAppointments); setSearch(''); notify('初期データに戻しました'); }} style={s.reset}><Text style={s.resetText}>リセット</Text></TouchableOpacity>
    </View>
    <KeyboardAvoidingView style={s.flex} behavior={Platform.OS === 'ios' ? 'padding' : undefined} keyboardVerticalOffset={62}>
      <ScrollView style={s.flex} contentContainerStyle={[s.content, { paddingHorizontal: compact ? 14 : 18 }]} keyboardShouldPersistTaps="handled">
        {!!error && <View style={s.error} accessibilityRole="alert" accessibilityLiveRegion="assertive"><Text style={s.errorText}>{error}</Text></View>}
        {route.type === 'tab' && route.tab === 'today' && <>
          <Text style={s.kicker}>{new Date().toLocaleDateString('ja-JP', { timeZone: 'Asia/Tokyo', year: 'numeric', month: 'long', day: 'numeric', weekday: 'long' })}</Text>
          <Text style={s.lead}>今日やる仕事から始めましょう。</Text>
          <Card title="期限超過" count="1件"><WorkRow title={`${customerById(overdueDeal?.customerId ?? '')?.name ?? '顧客'}様の商談を確認`} detail={`${overdueDeal?.next ?? '期限未設定'} · ${overdueDeal?.status ?? '要確認'} · ${overdueDeal?.staff ?? '担当未設定'}`} onPress={overdueDeal ? () => openDeal(overdueDeal) : undefined} /></Card>
          <Card title="今日の予約" count={`${appointments.length}件`}>{appointments.map((item) => <WorkRow key={item.id} title={item.name} detail={`${item.when} · ${item.subject}`} onPress={item.dealId ? () => { const deal = deals.find((candidate) => candidate.id === item.dealId); if (deal) openDeal(deal); } : item.customerId ? () => push({ type: 'customer', tab: 'today', id: item.customerId }) : item.vehicleId ? () => { setVehicleTab('基本'); push({ type: 'vehicle', tab: 'today', id: item.vehicleId }); } : undefined} />)}</Card>
          <Card title="入庫" count="1件"><WorkRow title={vehicleById(intakeJob?.vehicleId ?? '')?.name ?? '入庫予定'} detail={`${intakeJob?.date ?? '日時未設定'} · ${intakeJob?.request ?? '入庫予定'}`} onPress={intakeJob ? () => openJob(intakeJob) : undefined} /></Card>
          <Card title="納車" count={deliveryDeal ? '1件' : '0件'}><WorkRow title={deliveryDeal ? vehicleById(deliveryDeal.vehicleId)?.name ?? '納車予定' : '納車予定はありません'} detail={deliveryDeal ? `${customerById(deliveryDeal.customerId)?.name ?? '顧客'} · ${deliveryDeal.next}` : '本日の納車予定はありません'} onPress={deliveryDeal ? () => openDeal(deliveryDeal) : undefined} /></Card>
          <Card title="商談対応" count="2件"><WorkRow title={`${customerById(followUpDeal?.customerId ?? '')?.name ?? '顧客'}の商談フォロー`} detail={`${followUpDeal?.next ?? '次回未設定'} · ${followUpDeal?.staff ?? '担当未設定'}`} onPress={followUpDeal ? () => openDeal(followUpDeal) : undefined} /></Card>
          <Action title="期限超過の商談を確認" onPress={() => overdueDeal ? openDeal(overdueDeal) : goTab('deals')} />
          <Action title="予約を追加" kind="quiet" onPress={() => { clearDraftFields('appointmentCustomerId', 'appointmentVehicleId', 'appointmentDealId'); push({ type: 'appointmentCreate', tab: 'today' }); }} />
        </>}
        {route.type === 'tab' && route.tab === 'vehicles' && <>
          <View style={s.introLine}><Text style={s.lead}>在庫 {vehicles.length}台</Text><Action title="仕入を登録" onPress={() => push({ type: 'purchase', tab: 'vehicles', step: 1 })} compact /></View>
          <Input label="車名・管理番号で検索" value={search} onChangeText={setSearch} placeholder="例：GL-2401" />
          {filteredVehicles.length ? filteredVehicles.map((item) => <Entity key={item.id} title={item.name} detail={`${item.number} · ${item.status} · ${item.days}日`} onPress={() => { setVehicleTab('基本'); push({ type: 'vehicle', tab: 'vehicles', id: item.id }); }} />) : <Empty title="該当する車両はありません" detail="検索条件を確認するか、仕入を登録してください。" />}
        </>}
        {route.type === 'vehicle' && currentVehicle && <>
          <View style={s.hero}><Text style={s.heroTitle}>{currentVehicle.name}</Text><Text style={s.muted}>{currentVehicle.number}　·　{currentVehicle.status}</Text><View style={s.metrics}>{[[`${currentVehicle.days}日`, '在庫日数'], [`${currentVehicle.cost.toLocaleString()}円`, '総原価'], [`${currentVehicle.margin.toLocaleString()}円`, '予定粗利']].map(([num, label]) => <View key={label} style={s.metric}><Text style={s.metricNum}>{num}</Text><Text style={s.metricLabel}>{label}</Text></View>)}</View></View>
          <View style={s.vehicleTabs}>{['基本', '仕入', '写真', '販売', '関連'].map((name) => <TouchableOpacity key={name} accessibilityRole="button" accessibilityState={{ selected: vehicleTab === name }} onPress={() => setVehicleTab(name)} style={[s.vehicleTab, vehicleTab === name && s.vehicleTabOn]}><Text style={[s.vehicleTabText, vehicleTab === name && s.vehicleTabTextOn]}>{name}</Text></TouchableOpacity>)}</View>
          {vehicleTab === '基本' && <Card title="基本情報"><Info label="管理番号" value={currentVehicle.number} /><Info label="状態" value={currentVehicle.status} /><Info label="仕入先" value={currentVehicle.supplier} /></Card>}
          {vehicleTab === '仕入' && <Card title="仕入・原価">
            <Info label="仕入先" value={currentVehicle.supplier} />
            <Info label="仕入先種別" value={currentVehicle.supplierType || '未登録'} />
            <Info label="仕入日" value={currentVehicle.purchaseDate || '未登録'} />
            <Info label="走行距離" value={currentVehicle.mileage ? currentVehicle.mileage + 'km' : '未登録'} />
            <Info label="総原価" value={currentVehicle.cost.toLocaleString() + '円'} />
            <Info label="加修・諸経費" value={currentVehicleExtraCosts === undefined ? '詳細未登録' : currentVehicleExtraCosts.toLocaleString() + '円'} />
            <Action title={expanded.vehicleCosts ? '原価詳細を閉じる' : '原価の詳細を入力'} kind="quiet" onPress={() => {
              if (!expanded.vehicleCosts) {
                const costs = currentVehicle.costBreakdown;
                update('detailSupplier', currentVehicle.supplier);
                update('detailSupplierType', currentVehicle.supplierType || 'オークション');
                update('detailPurchaseDate', currentVehicle.purchaseDate || todayString);
                update('detailMileage', currentVehicle.mileage || '');
                update('detailPurchasePrice', String(costs?.purchasePrice ?? currentVehicle.cost));
                update('detailSpecial', String(costs?.specialCost ?? 0));
                update('detailAccessories', String(costs?.accessoryCost ?? 0));
                update('detailAgency', String(costs?.agentCost ?? 0));
                update('detailLegal', String(costs?.legalCost ?? 0));
                update('detailOther', String(costs?.otherCost ?? 0));
                update('detailRepair', String(costs?.repairCost ?? 0));
                update('detailAskingPrice', String(currentVehicle.price));
              }
              toggleExpanded('vehicleCosts');
            }} />
            {expanded.vehicleCosts && <>
              <Input label="仕入先" value={value('detailSupplier')} onChangeText={(text) => update('detailSupplier', text)} />
              <Choice label="仕入先種別" value={value('detailSupplierType') || 'オークション'} options={['オークション', '業者', '個人']} onSelect={(text) => update('detailSupplierType', text)} />
              <Input label="仕入日" value={value('detailPurchaseDate')} onChangeText={(text) => update('detailPurchaseDate', text)} />
              <Input label="走行距離（km）" value={value('detailMileage')} onChangeText={(text) => update('detailMileage', text)} keyboardType="numeric" />
              <Input label="仕入価格" value={value('detailPurchasePrice')} onChangeText={(text) => update('detailPurchasePrice', text)} keyboardType="numeric" />
              <Input label="特仕原価" value={value('detailSpecial')} onChangeText={(text) => update('detailSpecial', text)} keyboardType="numeric" />
              <Input label="付属品原価" value={value('detailAccessories')} onChangeText={(text) => update('detailAccessories', text)} keyboardType="numeric" />
              <Input label="手続代行原価" value={value('detailAgency')} onChangeText={(text) => update('detailAgency', text)} keyboardType="numeric" />
              <Input label="法定原価" value={value('detailLegal')} onChangeText={(text) => update('detailLegal', text)} keyboardType="numeric" />
              <Input label="その他経費" value={value('detailOther')} onChangeText={(text) => update('detailOther', text)} keyboardType="numeric" />
              <Input label="加修費" value={value('detailRepair')} onChangeText={(text) => update('detailRepair', text)} keyboardType="numeric" />
              <Input label="希望売価" value={value('detailAskingPrice')} onChangeText={(text) => update('detailAskingPrice', text)} keyboardType="numeric" />
              <Action title="原価を保存" onPress={() => {
                const base = Number(value('detailPurchasePrice')) || 0;
                const breakdown = { purchasePrice: base, specialCost: Number(value('detailSpecial')) || 0, accessoryCost: Number(value('detailAccessories')) || 0, agentCost: Number(value('detailAgency')) || 0, legalCost: Number(value('detailLegal')) || 0, otherCost: Number(value('detailOther')) || 0, repairCost: Number(value('detailRepair')) || 0 };
                const extra = Object.entries(breakdown).reduce((sum, [key, amount]) => sum + (key === 'purchasePrice' ? 0 : amount), 0);
                const cost = base + extra;
                const price = Number(value('detailAskingPrice')) || cost;
                setVehicles((items) => items.map((item) => item.id === currentVehicle.id ? { ...item, supplier: value('detailSupplier') || item.supplier, supplierType: value('detailSupplierType') || item.supplierType, purchaseDate: value('detailPurchaseDate') || item.purchaseDate, mileage: value('detailMileage'), costBreakdown: breakdown, cost, price, margin: price - cost } : item));
                toggleExpanded('vehicleCosts');
                notify('原価を保存しました');
              }} />
            </>}
          </Card>}
          {vehicleTab === '写真' && <Card title="写真"><Text style={s.muted}>写真区分ごとに記録します。</Text>{currentVehicle.photos.map((kind, index) => <WorkRow key={`${kind}${index}`} title={kind} detail="写真 1枚" />)}<Action title="写真を追加" onPress={() => push({ type: 'photo', tab: 'vehicles', id: currentVehicle.id })} /></Card>}
          {vehicleTab === '販売' && <Card title="販売"><Info label="掲載価格" value={`${currentVehicle.price.toLocaleString()}円`} /><Info label="予定粗利" value={`${currentVehicle.margin.toLocaleString()}円`} /></Card>}
          {vehicleTab === '関連' && <Card title="関連業務"><Action title="この車両で整備受付" onPress={() => openJobCreate(undefined, currentVehicle.id)} /><Action title="この車両で商談作成" kind="quiet" onPress={() => openVehicleDeal(currentVehicle.id)} /></Card>}
          <Action title={currentVehicle.status === '在庫中' ? '商談を作る' : currentVehicle.status === '整備中' ? '作業を確認' : '販売内容を確認'} onPress={() => currentVehicle.status === '整備中' ? openJobCreate(undefined, currentVehicle.id) : openVehicleDeal(currentVehicle.id)} />
        </>}
        {route.type === 'purchase' && <>
          <View style={s.progress}><View style={[s.progressDot, route.step! >= 1 && s.progressOn]} /><View style={[s.progressDot, route.step! >= 2 && s.progressOn]} /><View style={[s.progressDot, route.step! >= 3 && s.progressOn]} /><Text style={s.progressText}>{route.step === 1 ? '車両基本' : route.step === 2 ? '仕入・価格' : '写真・確認'}</Text></View>
          {route.step === 1 && <><Text style={s.lead}>まず車両を特定します。</Text><Input label="車名 *" value={value('vehicleName')} onChangeText={(text) => update('vehicleName', text)} placeholder="例：トヨタ プロボックス" /><Input label="管理番号" value={value('managementNo')} onChangeText={(text) => update('managementNo', text)} placeholder="未設定でも登録できます" /><Input label="走行距離（km）" value={value('mileage')} onChangeText={(text) => update('mileage', text)} keyboardType="numeric" placeholder="例：42000" /><Action title="仕入情報へ" onPress={() => { if (!value('vehicleName').trim()) setError('車名を入力してください。'); else { setError(''); setRoute({ ...route, step: 2 }); } }} />
          </>}
          {route.step === 2 && <>
            <Text style={s.lead}>仕入先と金額を登録します。</Text>
            <Input label="仕入先 *" value={value('supplier')} onChangeText={(text) => update('supplier', text)} placeholder="仕入先名" />
            <Choice label="仕入先種別" value={value('supplierType') || 'オークション'} options={['オークション', '業者', '個人']} onSelect={(text) => update('supplierType', text)} />
            <Input label="仕入日 *" value={value('purchaseDate') || todayString} onChangeText={(text) => update('purchaseDate', text)} placeholder="YYYY-MM-DD" />
            <Input label="仕入価格 *" value={value('purchasePrice')} onChangeText={(text) => update('purchasePrice', text)} keyboardType="numeric" placeholder="円" />
            <Input label="希望売価（任意）" value={value('askingPrice')} onChangeText={(text) => update('askingPrice', text)} keyboardType="numeric" placeholder="円" />
            <Action title={expanded.purchaseCosts ? '原価の詳細を閉じる' : '原価項目を追加（任意）'} kind="quiet" compact onPress={() => toggleExpanded('purchaseCosts')} />
            {expanded.purchaseCosts && <Card title="追加原価"><Input label="特仕原価" value={value('specialCost')} onChangeText={(text) => update('specialCost', text)} keyboardType="numeric" placeholder="円" /><Input label="付属品原価" value={value('accessoryCost')} onChangeText={(text) => update('accessoryCost', text)} keyboardType="numeric" placeholder="円" /><Input label="手続代行原価" value={value('agentCost')} onChangeText={(text) => update('agentCost', text)} keyboardType="numeric" placeholder="円" /><Input label="法定原価" value={value('legalCost')} onChangeText={(text) => update('legalCost', text)} keyboardType="numeric" placeholder="円" /><Input label="その他経費" value={value('otherCost')} onChangeText={(text) => update('otherCost', text)} keyboardType="numeric" placeholder="円" /><Input label="加修費" value={value('repairCost')} onChangeText={(text) => update('repairCost', text)} keyboardType="numeric" placeholder="円" /><Info label="総原価（自動計算）" value={`${(Number(value('purchasePrice') || 0) + ['specialCost', 'accessoryCost', 'agentCost', 'legalCost', 'otherCost', 'repairCost'].reduce((sum, key) => sum + (Number(value(key)) || 0), 0)).toLocaleString()}円`} /></Card>}
            <Text style={s.helper}>追加原価は後から登録できます。総原価は自動計算します。</Text>
            <Action title="写真・状態へ" onPress={() => { if (!value('supplier').trim() || !value('purchasePrice').trim()) setError('仕入先と仕入価格を入力してください。'); else { setError(''); setRoute({ ...route, step: 3 }); } }} />
          </>}
          {route.step === 3 && <><Text style={s.lead}>写真区分を選び、仕入内容を保存します。</Text><View style={s.chipWrap}>{photoKinds.map((kind) => <Chip key={kind} label={kind} selected={selectedPhotoKind === kind} onPress={() => setSelectedPhotoKind(kind)} />)}</View><Card title="登録内容"><Info label="車両" value={value('vehicleName')} /><Info label="仕入先" value={value('supplier')} /><Info label="仕入日" value={value('purchaseDate') || todayString} /><Info label="仕入価格" value={`${Number(value('purchasePrice') || 0).toLocaleString()}円`} /><Info label="総原価（自動計算）" value={`${(Number(value('purchasePrice') || 0) + ['specialCost', 'accessoryCost', 'agentCost', 'legalCost', 'otherCost', 'repairCost'].reduce((sum, key) => sum + (Number(value(key)) || 0), 0)).toLocaleString()}円`} /><Info label="予定粗利（自動計算）" value={`${((Number(value('askingPrice')) || Number(value('purchasePrice')) || 0) - (Number(value('purchasePrice') || 0) + ['specialCost', 'accessoryCost', 'agentCost', 'legalCost', 'otherCost', 'repairCost'].reduce((sum, key) => sum + (Number(value(key)) || 0), 0))).toLocaleString()}円`} /></Card><Text style={s.helper}>写真本体は試作では保存しません。</Text><Action title="仕入を保存" onPress={saveVehicle} /></>}
        </>}
        {route.type === 'tab' && route.tab === 'customers' && <>
          <View style={s.introLine}><Text style={s.lead}>顧客 {customers.length}名</Text><Action title="顧客を登録" onPress={() => push({ type: 'customerCreate', tab: 'customers' })} compact /></View>
          <Input label="名前・電話番号で検索" value={search} onChangeText={setSearch} placeholder="検索" />
          {filteredCustomers.length ? filteredCustomers.map((item) => <Entity key={item.id} title={item.name} detail={item.phone} onPress={() => push({ type: 'customer', tab: 'customers', id: item.id })} />) : <Empty title="顧客が見つかりません" detail="検索条件を確認するか、新規登録してください。" />}
        </>}
        {route.type === 'customerCreate' && <>
          <Text style={s.lead}>名前と電話番号だけで先に登録できます。</Text>
          <Input label="名前 *" value={value('customerName')} onChangeText={(text) => update('customerName', text)} placeholder="例：山田 太郎" />
          <Input label="電話番号 *" value={value('customerPhone')} onChangeText={(text) => update('customerPhone', text)} keyboardType={Platform.OS === 'web' ? 'default' : 'phone-pad'} placeholder="例：090-0000-0000" />
          <Action title={expanded.customerDetails ? '詳細項目を閉じる' : '住所・希望条件を追加（任意）'} kind="quiet" compact onPress={() => toggleExpanded('customerDetails')} />
          {expanded.customerDetails && <Card title="顧客の詳細"><Choice label="個人／法人" value={value('customerType') || '個人'} options={['個人', '法人']} onSelect={(text) => update('customerType', text)} /><Input label="メール" value={value('customerEmail')} onChangeText={(text) => update('customerEmail', text)} keyboardType="default" placeholder="任意" /><Input label="住所" value={value('customerAddress')} onChangeText={(text) => update('customerAddress', text)} placeholder="後から追加できます" /><Input label="希望車種" value={value('desiredVehicle')} onChangeText={(text) => update('desiredVehicle', text)} /><Input label="予算" value={value('customerBudget')} onChangeText={(text) => update('customerBudget', text)} keyboardType="numeric" /><Input label="購入希望時期" value={value('purchaseTiming')} onChangeText={(text) => update('purchaseTiming', text)} /><Input label="下取り" value={value('tradeIn')} onChangeText={(text) => update('tradeIn', text)} /><Input label="担当者・次回対応" value={value('customerStaff')} onChangeText={(text) => update('customerStaff', text)} /><Input label="メモ" value={value('customerNote')} onChangeText={(text) => update('customerNote', text)} multiline /></Card>}
          <Action title="顧客を保存" onPress={saveCustomer} />
        </>}
        {route.type === 'customer' && currentCustomer && <><View style={s.hero}><Text style={s.heroTitle}>{currentCustomer.name}</Text><Text style={s.muted}>{currentCustomer.phone}</Text></View><Card title="顧客情報"><Info label="電話" value={currentCustomer.phone} /><Info label="メール" value={currentCustomer.email || '未登録'} /><Info label="種別" value={currentCustomer.kind || '個人'} /><Info label="住所" value={currentCustomer.address || '未登録'} /><Info label="希望車種・予算" value={[currentCustomer.desiredVehicle, currentCustomer.budget].filter(Boolean).join(' · ') || '未登録'} /><Info label="希望時期・下取り" value={[currentCustomer.purchaseTiming, currentCustomer.tradeIn].filter(Boolean).join(' · ') || '未登録'} /><Info label="担当・次回対応" value={[currentCustomer.staff, currentCustomer.next].filter(Boolean).join(' · ') || '未登録'} /><Info label="メモ" value={currentCustomer.note || 'なし'} /><Info label="状態" value="対応中" /><Action title="顧客情報を編集" kind="quiet" onPress={() => { update('customerName', currentCustomer.name); update('customerPhone', currentCustomer.phone); update('customerEmail', currentCustomer.email || ''); update('customerType', currentCustomer.kind || '個人'); update('customerAddress', currentCustomer.address || ''); update('desiredVehicle', currentCustomer.desiredVehicle || ''); update('customerBudget', currentCustomer.budget || ''); update('purchaseTiming', currentCustomer.purchaseTiming || ''); update('tradeIn', currentCustomer.tradeIn || ''); update('customerStaff', currentCustomer.staff || ''); update('customerNext', currentCustomer.next || ''); update('customerNote', currentCustomer.note || ''); setExpanded((current) => ({ ...current, customerDetails: true })); push({ type: 'customerCreate', tab: 'customers', id: currentCustomer.id }); }} /><Action title="電話をかける（試作）" kind="quiet" onPress={() => notify('電話アプリ起動の接続位置です')} /><Action title="メールを作成（試作）" kind="quiet" onPress={() => notify('メール作成の接続位置です')} /></Card><Card title="関連業務"><Action title="この顧客で商談を作る" onPress={() => openCustomerDeal(currentCustomer.id)} /><Action title="この顧客で整備受付" kind="quiet" onPress={() => openJobCreate(currentCustomer.id)} /><Action title="予約を登録" kind="quiet" onPress={() => { clearDraftFields('appointmentVehicleId', 'appointmentDealId'); update('appointmentName', '来店相談'); update('appointmentSubject', currentCustomer.name); update('appointmentCustomerId', currentCustomer.id); update('appointmentDate', todayString); push({ type: 'appointmentCreate', tab: 'customers' }); }} /></Card></>}
        {route.type === 'tab' && route.tab === 'deals' && <><View style={s.introLine}><Text style={s.lead}>商談 {deals.length}件</Text><Action title="商談を作成" onPress={() => push({ type: 'dealCreate', tab: 'deals' })} compact /></View>{deals.map((item) => <Entity key={item.id} title={customerById(item.customerId)?.name ?? '顧客未設定'} detail={`${vehicleById(item.vehicleId)?.name ?? '車両未設定'} · ${item.status} · 次回 ${item.next}`} badge={item.certainty} onPress={() => openDeal(item)} />)}</>}
        {route.type === 'dealCreate' && <>
          <Text style={s.lead}>顧客・車両は前画面から引き継ぎます。</Text>
          <Choice label="顧客" value={customerById(value('dealCustomerId'))?.name ?? '選択してください'} options={customers.map(customerOption)} onSelect={(option) => update('dealCustomerId', customers.find((item) => customerOption(item) === option)?.id ?? '')} />
          <Choice label="車両" value={vehicleById(value('dealVehicleId'))?.name ?? '選択してください'} options={vehicles.map(vehicleOption)} onSelect={(option) => update('dealVehicleId', vehicles.find((item) => vehicleOption(item) === option)?.id ?? '')} />
          <Info label="状態" value="新規" />
          <Input label="次回対応" value={value('dealNext')} onChangeText={(text) => update('dealNext', text)} placeholder="例：明日 10:00" />
          <Input label="担当者" value={value('dealStaff') || '田中'} onChangeText={(text) => update('dealStaff', text)} />
          <Choice label="確度" value={value('dealCertainty') || '30%'} options={['30%', '60%', '80%']} onSelect={(text) => update('dealCertainty', text)} />
          <Action title={expanded.dealDetails ? '追加項目を閉じる' : '予算・下取りなどを追加（任意）'} kind="quiet" compact onPress={() => toggleExpanded('dealDetails')} />
          {expanded.dealDetails && <Card title="商談の詳細"><Input label="流入元" value={value('dealSource')} onChangeText={(text) => update('dealSource', text)} placeholder="紹介・Webなど" /><Input label="予算" value={value('dealBudget')} onChangeText={(text) => update('dealBudget', text)} keyboardType="numeric" /><Input label="下取り" value={value('dealTradeIn')} onChangeText={(text) => update('dealTradeIn', text)} /><Choice label="ローン希望" value={value('loanWish') || '未確認'} options={['未確認', '希望する', '希望しない']} onSelect={(text) => update('loanWish', text)} /><Input label="メモ" value={value('dealNote')} onChangeText={(text) => update('dealNote', text)} multiline /></Card>}
          <Action title="商談を保存" onPress={saveDeal} />
        </>}
        {route.type === 'deal' && currentDeal && <>
          <View style={s.hero}><Text style={s.heroTitle}>{currentDeal.status}</Text><Text style={s.muted}>{customerById(currentDeal.customerId)?.name} · {vehicleById(currentDeal.vehicleId)?.name}</Text><Text style={s.muted}>次回 {currentDeal.next} · 担当 {currentDeal.staff}</Text></View>
          <Action title={currentDeal.status === '新規' || currentDeal.status === '見積前' ? '見積を作る' : currentDeal.status === '見積提示済み' ? '成約にする' : currentDeal.status === '成約' ? '入金を登録' : currentDeal.status === '入金済み' ? '納車を完了' : '成約済み'} onPress={() => dealPrimary(currentDeal)} />
          <Card title="商談情報">
            <Info label="確度" value={currentDeal.certainty} />
            <Info label="流入元" value={currentDeal.source || '未登録'} />
            <Info label="予算" value={currentDeal.budget || '未登録'} />
            <Info label="下取り" value={currentDeal.tradeIn || '未登録'} />
            <Info label="ローン希望" value={currentDeal.loanWish || '未登録'} />
            <Info label="メモ" value={currentDeal.note || 'なし'} />
            {currentDeal.quoteAmount ? <Info label={'見積 ' + (currentDeal.quoteItem || '')} value={Number(currentDeal.quoteAmount).toLocaleString() + '円'} /> : null}
            {currentDeal.paidAmount ? <Info label={'入金 ' + (currentDeal.paymentMethod || '')} value={Number(currentDeal.paidAmount).toLocaleString() + '円'} /> : null}
          </Card>
          <Card title="補助操作">
            <Action title="対応メモを追加" kind="quiet" onPress={() => notify('対応メモ欄を開きました')} />
            <Action title="予約を登録" kind="quiet" onPress={() => { update('appointmentName', '商談フォロー'); update('appointmentSubject', [customerById(currentDeal.customerId)?.name, vehicleById(currentDeal.vehicleId)?.name].filter(Boolean).join(' · ')); update('appointmentCustomerId', currentDeal.customerId); update('appointmentVehicleId', currentDeal.vehicleId); update('appointmentDealId', currentDeal.id); update('appointmentDate', todayString); push({ type: 'appointmentCreate', tab: 'deals', id: currentDeal.id }); }} />
            <TouchableOpacity accessibilityRole="button" onPress={() => push({ type: 'dealCancel', tab: 'deals', id: currentDeal.id })} style={s.dangerLink}><Text style={s.dangerText}>売約を取り消す…</Text></TouchableOpacity>
          </Card>
        </>}
        {route.type === 'dealCancel' && currentDeal && <><View style={s.error} accessibilityRole="alert" accessibilityLiveRegion="assertive"><Text style={s.errorText}>売約を取り消すと商談状態が変わります。対象と理由を確認してください。</Text></View><Card title="対象"><Info label="顧客" value={customerById(currentDeal.customerId)?.name ?? '-'} /><Info label="車両" value={vehicleById(currentDeal.vehicleId)?.name ?? '-'} /><Info label="現在の状態" value={currentDeal.status} /></Card><Input label="取消理由 *" value={value('cancelReason')} onChangeText={(text) => update('cancelReason', text)} placeholder="理由を記録" multiline /><Action title="売約取消を確定" onPress={() => { if (!value('cancelReason').trim()) { setError('取消理由を入力してください。'); return; } setDeals((items) => items.map((item) => item.id === currentDeal.id ? { ...item, status: '売約取消', note: value('cancelReason').trim() } : item)); clearDraftFields('cancelReason'); notify('取消を記録しました'); goTab('deals'); }} /><Action title="戻る" kind="quiet" onPress={back} /></>}
        {route.type === 'quoteCreate' && <><Text style={s.lead}>見積の基本情報を入力します。</Text><Info label="顧客" value={customerById(currentDeal?.customerId ?? currentJob?.customerId ?? '')?.name ?? '顧客'} /><Info label="車両" value={vehicleById(currentDeal?.vehicleId ?? currentJob?.vehicleId ?? '')?.name ?? '車両'} /><Input label="見積項目 *" value={value('quoteItem')} onChangeText={(text) => update('quoteItem', text)} placeholder="車両本体価格" /><Input label="金額 *" value={value('quoteAmount')} onChangeText={(text) => update('quoteAmount', text)} keyboardType="numeric" placeholder="円" /><Action title="見積を保存" onPress={() => { if (!value('quoteItem').trim() || !value('quoteAmount').trim()) setError('項目と金額を入力してください。'); else { if (route.tab === 'deals') setDeals((items) => items.map((item) => item.id === route.id ? { ...item, status: '見積提示済み', quoteItem: value('quoteItem').trim(), quoteAmount: value('quoteAmount').trim() } : item)); else if (route.tab === 'maintenance') setJobs((items) => items.map((item) => item.id === route.id ? { ...item, quoteItem: value('quoteItem').trim(), quoteAmount: value('quoteAmount').trim(), estimateInvoice: value('quoteAmount').trim() } : item)); clearDraftFields('quoteItem', 'quoteAmount'); notify('見積を保存しました'); back(); } }} /></>}
        {route.type === 'paymentCreate' && <><Text style={s.lead}>入金を記録します。</Text><Info label="顧客" value={customerById(currentDeal?.customerId ?? '')?.name ?? '顧客'} /><Input label="入金額 *" value={value('paymentAmount')} onChangeText={(text) => update('paymentAmount', text)} keyboardType="numeric" placeholder="円" /><Choice label="支払方法" value={value('paymentMethod') || '振込'} options={['振込', '現金', 'カード', 'ローン']} onSelect={(text) => update('paymentMethod', text)} /><Action title="入金を登録" onPress={() => { if (!value('paymentAmount').trim()) setError('入金額を入力してください。'); else { setDeals((items) => items.map((item) => item.id === route.id ? { ...item, status: '入金済み', paidAmount: value('paymentAmount').trim(), paymentMethod: value('paymentMethod') || '振込' } : item)); clearDraftFields('paymentAmount', 'paymentMethod'); notify('入金を登録しました'); back(); } }} /></>}
        {route.type === 'delivery' && <><Text style={s.lead}>納車内容を確認してください。</Text><Card title="納車内容"><Info label="顧客" value={customerById(currentDeal?.customerId ?? '')?.name ?? '-'} /><Info label="車両" value={vehicleById(currentDeal?.vehicleId ?? '')?.name ?? '-'} /><Info label="状態" value="入金済み" /></Card><Action title="納車を完了" onPress={() => { setDeals((items) => items.map((item) => item.id === route.id ? { ...item, status: '納車済み', delivered: true } : item)); notify('納車を記録しました'); back(); }} /><Text style={s.helper}>完了記録は確認画面を経由します。</Text></>}
        {route.type === 'tab' && route.tab === 'maintenance' && <><View style={s.introLine}><Text style={s.lead}>整備 {jobs.length}件</Text><Action title="整備を受付" onPress={() => openJobCreate()} compact /></View>{jobs.length ? jobs.map((item) => <Entity key={item.id} title={vehicleById(item.vehicleId)?.name ?? '車両'} detail={`${item.request} · ${item.status} · ${item.date}`} onPress={() => openJob(item)} />) : <Empty title="整備案件はありません" detail="整備を受付から登録できます。" />}</>}
        {route.type === 'maintenanceCreate' && <><Text style={s.lead}>最低限を入力して受付。費用・部品は後から追加できます。</Text><Choice label="顧客" value={customerById(value('jobCustomerId'))?.name ?? '選択してください'} options={customers.map(customerOption)} onSelect={(option) => update('jobCustomerId', customers.find((item) => customerOption(item) === option)?.id ?? '')} /><Choice label="車両" value={vehicleById(value('jobVehicleId'))?.name ?? '選択してください'} options={vehicles.map(vehicleOption)} onSelect={(option) => update('jobVehicleId', vehicles.find((item) => vehicleOption(item) === option)?.id ?? '')} /><Input label="依頼内容 *" value={value('jobRequest')} onChangeText={(text) => update('jobRequest', text)} placeholder="例：12か月点検" /><Input label="症状 *" value={value('jobSymptom')} onChangeText={(text) => update('jobSymptom', text)} placeholder="気になる症状" multiline /><Input label="担当" value={value('jobStaff') || '田中'} onChangeText={(text) => update('jobStaff', text)} /><Input label="入庫予定" value={value('intakeDate') || todayString} onChangeText={(text) => update('intakeDate', text)} /><Action title="整備受付を保存" onPress={saveJob} /></>}
        {route.type === 'maintenance' && currentJob && <MaintenanceDetailPrototype job={currentJob} customerName={customerById(currentJob.customerId)?.name ?? '-'} vehicleName={vehicleById(currentJob.vehicleId)?.name ?? '-'} tab={maintenanceTab} setTab={setMaintenanceTab} value={value} update={update} onAdvance={() => setJobs((items) => items.map((item) => item.id === currentJob.id ? { ...item, status: item.status === '受付' || item.status === '入庫待ち' ? '入庫済み' : item.status === '入庫済み' ? '作業中' : item.status === '作業中' ? '完了' : item.status } : item))} onPhoto={() => { setSelectedPhotoKind('整備中'); push({ type: 'photo', tab: 'maintenance', id: currentJob.id }); }} onQuote={() => { update('quoteItem', currentJob.request); update('quoteAmount', currentJob.estimateInvoice || ''); push({ type: 'quoteCreate', tab: 'maintenance', id: currentJob.id }); }} onBill={() => { update('jobBilledAmount', currentJob.billedAmount || currentJob.estimateInvoice || ''); update('jobPaymentMethod', currentJob.paymentMethod || ''); push({ type: 'jobBilling', tab: 'maintenance', id: currentJob.id }); }} onSave={() => { setJobs((items) => items.map((item) => item.id === currentJob.id ? { ...item, workItems: value('workItems'), parts: value('parts'), workInstruction: value('workInstruction'), priority: value('priority'), workSchedule: value('workSchedule'), deliveryPlan: value('deliveryPlan'), actualDates: value('actualDates'), loaner: value('loaner'), laborCost: value('laborCost'), partsCost: value('partsCost'), inspectionFees: value('inspectionFees'), adjustments: value('adjustments'), estimateInvoice: value('estimateInvoice'), estimateApproval: value('estimateApproval'), paymentMethod: value('jobPaymentMethod') } : item)); notify('整備内容を保存しました'); }} />}
        {route.type === 'jobBilling' && currentJob && <><Text style={s.lead}>作業内容と金額を確認して請求を記録します。</Text><Card title="整備案件"><Info label="依頼" value={currentJob.request} /><Info label="顧客" value={customerById(currentJob.customerId)?.name ?? '-'} /><Info label="車両" value={vehicleById(currentJob.vehicleId)?.name ?? '-'} /></Card><Input label="請求額 *" value={value('jobBilledAmount')} onChangeText={(text) => update('jobBilledAmount', text)} keyboardType="numeric" placeholder="円" /><Choice label="支払方法" value={value('jobPaymentMethod') || '未定'} options={['未定', '現金', '振込', 'カード', 'ローン']} onSelect={(text) => update('jobPaymentMethod', text)} /><Action title="請求を保存" onPress={() => { if (!value('jobBilledAmount').trim()) setError('請求額を入力してください。'); else { setJobs((items) => items.map((item) => item.id === currentJob.id ? { ...item, status: '請求済み', billedAmount: value('jobBilledAmount').trim(), paymentMethod: value('jobPaymentMethod') || '未定' } : item)); clearDraftFields('jobBilledAmount', 'jobPaymentMethod'); notify('請求を保存しました'); back(); } }} /></>}
        {route.type === 'photo' && <><Text style={s.lead}>写真の分類を選びます。</Text><View style={s.chipWrap}>{photoKinds.map((kind) => <Chip key={kind} label={kind} selected={selectedPhotoKind === kind} onPress={() => setSelectedPhotoKind(kind)} />)}</View><Card title="撮影・選択"><Text style={s.body}>この試作ではカメラ／ライブラリへの接続は行わず、画面遷移と分類操作を確認します。</Text><Action title="撮影画面を開く（試作）" onPress={() => notify(`${selectedPhotoKind}の写真追加を記録しました`)} /><Action title="写真から選ぶ（試作）" kind="quiet" onPress={() => notify(`${selectedPhotoKind}に追加しました`)} /></Card><Action title="写真分類を保存" onPress={() => { if (route.tab === 'maintenance') setJobs((items) => items.map((item) => item.id === route.id ? { ...item, photos: [...(item.photos || []), selectedPhotoKind] } : item)); else setVehicles((items) => items.map((item) => item.id === route.id ? { ...item, photos: [...item.photos, selectedPhotoKind] } : item)); notify(route.tab === 'maintenance' ? '整備案件に写真分類を保存しました' : '車両に写真分類を保存しました'); back(); }} /></>}
        {route.type === 'appointmentCreate' && <><Text style={s.lead}>予約を短く記録します。</Text><Input label="予約内容 *" value={value('appointmentName')} onChangeText={(text) => update('appointmentName', text)} placeholder="例：車両相談" /><Input label="日時" value={value('appointmentDate') || todayString} onChangeText={(text) => update('appointmentDate', text)} /><Input label="顧客・車両" value={value('appointmentSubject')} onChangeText={(text) => update('appointmentSubject', text)} placeholder="選択または入力" /><Action title="予約を保存" onPress={saveAppointment} /></>}
      </ScrollView>
      {!!toast && <View style={s.toast} accessibilityRole="alert" accessibilityLiveRegion="polite"><Text style={s.toastText}>{toast}</Text></View>}
    </KeyboardAvoidingView>
    <View style={s.nav}>{tabs.map((item) => <TouchableOpacity key={item.id} onPress={() => goTab(item.id)} style={[s.navItem, route.tab === item.id && s.navItemOn]} accessibilityRole="button" accessibilityState={{ selected: route.tab === item.id }} accessibilityLabel={item.label}><Text style={[s.navGlyph, route.tab === item.id && s.navActive]}>{item.glyph}</Text><Text style={[s.navLabel, route.tab === item.id && s.navActive]}>{item.label}</Text></TouchableOpacity>)}</View>
  </SafeAreaView>;
}

function MaintenanceDetailPrototype({ job, customerName, vehicleName, tab, setTab, value, update, onAdvance, onPhoto, onQuote, onBill, onSave }: { job: Job; customerName: string; vehicleName: string; tab: string; setTab: (tab: string) => void; value: (key: string) => string; update: (key: string, value: string) => void; onAdvance: () => void; onPhoto: () => void; onQuote: () => void; onBill: () => void; onSave: () => void }) {
  const primary = job.status === '受付' || job.status === '入庫待ち' ? '入庫にする' : job.status === '入庫済み' ? '作業を開始' : job.status === '作業中' ? '作業を完了' : '請求を作る';
  return <>
    <View style={s.hero}><Text style={s.heroTitle}>{job.request}</Text><Text style={s.muted}>{customerName} · {vehicleName}</Text><Text style={s.muted}>{job.status} · 入庫 {job.date} · 担当 {job.staff}</Text></View>
    <View style={s.vehicleTabs}>{['受付', '作業', '費用', '写真'].map((name) => <TouchableOpacity key={name} accessibilityRole="button" accessibilityState={{ selected: tab === name }} onPress={() => setTab(name)} style={[s.vehicleTab, tab === name && s.vehicleTabOn]}><Text style={[s.vehicleTabText, tab === name && s.vehicleTabTextOn]}>{name}</Text></TouchableOpacity>)}</View>
    {tab === '受付' && <><Card title="依頼・症状"><Info label="依頼内容" value={job.request} /><Text style={s.body}>{job.symptom}</Text><Info label="入庫予定" value={job.date} /><Info label="担当" value={job.staff} /></Card><Action title={primary} onPress={job.status === '完了' ? onBill : onAdvance} /><Action title="作業写真を追加" kind="quiet" onPress={onPhoto} /></>}
    {tab === '作業' && <><Text style={s.lead}>作業の段取りをまとめて確認します。</Text><Input label="作業項目" value={value('workItems')} onChangeText={(text) => update('workItems', text)} placeholder="例：点検・ブレーキ調整" multiline /><Input label="使用部品" value={value('parts')} onChangeText={(text) => update('parts', text)} placeholder="品名・数量" /><Input label="作業指示" value={value('workInstruction')} onChangeText={(text) => update('workInstruction', text)} multiline /><Input label="担当・優先度" value={value('priority')} onChangeText={(text) => update('priority', text)} placeholder="担当者・優先度" /><Input label="入庫／作業開始予定" value={value('workSchedule')} onChangeText={(text) => update('workSchedule', text)} placeholder="日時" /><Input label="完了／納車予定" value={value('deliveryPlan')} onChangeText={(text) => update('deliveryPlan', text)} placeholder="日時" /><Input label="実入庫・実完了・実納車" value={value('actualDates')} onChangeText={(text) => update('actualDates', text)} placeholder="実績日時" /><Input label="代車" value={value('loaner')} onChangeText={(text) => update('loaner', text)} placeholder="車両・なし" /><Action title="作業計画を保存" onPress={onSave} /><Action title="作業写真を追加" kind="quiet" onPress={onPhoto} /></>}
    {tab === '費用' && <><Text style={s.lead}>金額は入力した費目から集計する想定です。</Text><Input label="工賃" value={value('laborCost')} onChangeText={(text) => update('laborCost', text)} keyboardType="numeric" placeholder="円" /><Input label="部品代" value={value('partsCost')} onChangeText={(text) => update('partsCost', text)} keyboardType="numeric" placeholder="円" /><Input label="車検・法定費用" value={value('inspectionFees')} onChangeText={(text) => update('inspectionFees', text)} keyboardType="numeric" placeholder="円" /><Input label="追加費用・値引き" value={value('adjustments')} onChangeText={(text) => update('adjustments', text)} placeholder="費用／値引き" /><Input label="見積額・請求額" value={value('estimateInvoice')} onChangeText={(text) => update('estimateInvoice', text)} keyboardType="numeric" placeholder="円" /><Choice label="支払方法" value={value('jobPaymentMethod') || '未定'} options={['未定', '現金', '振込', 'カード', 'ローン']} onSelect={(text) => update('jobPaymentMethod', text)} /><Choice label="見積承認" value={value('estimateApproval') || '未確認'} options={['未確認', '承認済み', '差戻し']} onSelect={(text) => update('estimateApproval', text)} /><Action title="費用・承認を保存" onPress={onSave} /><Action title="請求内容を作る" kind="quiet" onPress={onQuote} /></>}
    {tab === '写真' && <><Card title="整備写真"><Text style={s.body}>整備案件から直接写真を追加できます。</Text><Text style={s.muted}>撮影前・作業中・完了後に分けて記録します。</Text>{(job.photos || []).map((kind, index) => <WorkRow key={`${kind}${index}`} title={kind} detail="この案件に分類を保存" />)}</Card><Action title="整備写真を追加" onPress={onPhoto} /></>}
  </>;
}

function Card({ title, count, onPress, children }: { title: string; count?: string; onPress?: () => void; children: React.ReactNode }) { return <View style={s.card}><View style={s.cardTitleRow}><Text style={s.cardTitle}>{title}</Text>{count ? <Text style={s.count}>{count}</Text> : null}{onPress ? <TouchableOpacity accessibilityRole="button" onPress={onPress}><Text style={s.link}>開く ›</Text></TouchableOpacity> : null}</View>{children}</View>; }
function WorkRow({ title, detail, onPress }: { title: string; detail: string; onPress?: () => void }) { const content = <><View style={{ flexDirection: 'row', alignItems: 'center', justifyContent: 'space-between', gap: 8 }}><Text style={[s.workTitle, { flex: 1 }]}>{title}</Text>{onPress ? <Text style={s.chevron}>›</Text> : null}</View><Text style={s.workDetail}>{detail}</Text></>; return onPress ? <TouchableOpacity accessibilityRole="button" onPress={onPress} style={s.workRow}>{content}</TouchableOpacity> : <View style={s.workRow}>{content}</View>; }
function Entity({ title, detail, badge, onPress }: { title: string; detail: string; badge?: string; onPress: () => void }) { return <TouchableOpacity onPress={onPress} accessibilityRole="button" style={s.entity}><View style={s.entityBody}><Text style={s.entityTitle} numberOfLines={2}>{title}</Text><Text style={s.entityDetail} numberOfLines={2}>{detail}</Text></View>{badge ? <Text style={s.badge}>{badge}</Text> : <Text style={s.chevron}>›</Text>}</TouchableOpacity>; }
function Input({ label, value, onChangeText, placeholder, keyboardType, multiline = false }: { label: string; value: string; onChangeText: (value: string) => void; placeholder?: string; keyboardType?: 'default' | 'numeric' | 'phone-pad'; multiline?: boolean }) { return <View style={s.field}><Text style={s.label}>{label}</Text><TextInput accessibilityLabel={label} value={value} onChangeText={onChangeText} placeholder={placeholder} placeholderTextColor="#718096" keyboardType={keyboardType} multiline={multiline} textAlignVertical={multiline ? 'top' : 'center'} style={[s.input, multiline && s.multiline]} /></View>; }
function Choice({ label, value, options, onSelect }: { label: string; value: string; options: string[]; onSelect: (value: string) => void }) { const [open, setOpen] = useState(false); return <View style={s.field}><Text style={s.label}>{label}</Text><TouchableOpacity onPress={() => setOpen((current) => !current)} style={s.choice} accessibilityRole="button"><Text style={s.choiceValue}>{value}</Text><Text style={s.link}>{open ? '閉じる' : '変更'}</Text></TouchableOpacity>{open && <View style={s.optionList}>{options.map((option) => <TouchableOpacity key={option} onPress={() => { onSelect(option); setOpen(false); }} style={s.option}><Text style={s.body}>{option}</Text></TouchableOpacity>)}</View>}</View>; }
function Chip({ label, selected, onPress }: { label: string; selected: boolean; onPress: () => void }) { return <TouchableOpacity accessibilityRole="button" accessibilityState={{ selected }} onPress={onPress} style={[s.chip, selected && s.chipOn]}><Text style={[s.chipText, selected && s.chipTextOn]}>{label}</Text></TouchableOpacity>; }
function Info({ label, value }: { label: string; value: string }) { return <View style={s.info}><Text style={s.infoLabel}>{label}</Text><Text style={s.infoValue}>{value || '-'}</Text></View>; }
function Action({ title, onPress, kind = 'primary', compact = false }: { title: string; onPress: () => void; kind?: 'primary' | 'quiet'; compact?: boolean }) { return <TouchableOpacity onPress={onPress} accessibilityRole="button" style={[s.action, kind === 'quiet' && s.actionQuiet, compact && s.actionCompact]}><Text style={[s.actionText, kind === 'quiet' && s.actionQuietText]}>{title}</Text></TouchableOpacity>; }
function Empty({ title, detail }: { title: string; detail: string }) { return <View style={s.empty}><Text style={s.emptyTitle}>{title}</Text><Text style={s.muted}>{detail}</Text></View>; }

